fn is_letter(c: Str) -> Bool {
  return "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ".contains(c)
}

fn is_digit(c: Str) -> Bool {
  return "0123456789".contains(c)
}

fn is_space(c: Str) -> Bool {
  return " \t\n\r".contains(c)
}

fn is_two_op(s: Str) -> Bool {
  return ["==", "!=", "<=", ">=", "->"].contains(s)
}

fn is_single_op(c: Str) -> Bool {
  return "+-*/<>=(){},;".contains(c)
}

pub fn tokens(src: Str) -> Result[List[Str], Str] {
  let cs = src.chars()
  let n = cs.len()
  var out: List[Str] = []
  var i = 0
  while i < n {
    let c = cs.get_or(i, "")
    if is_space(c) {
      i = i + 1
    } else if is_letter(c) or c == "_" {
      var j = i + 1
      while j < n and (is_letter(cs.get_or(j, "")) or is_digit(cs.get_or(j, "")) or cs.get_or(j, "") == "_") {
        j = j + 1
      }
      out = out.push(cs.slice(i, j).join(""))
      i = j
    } else if is_digit(c) {
      var j = i + 1
      while j < n and is_digit(cs.get_or(j, "")) {
        j = j + 1
      }
      out = out.push(cs.slice(i, j).join(""))
      i = j
    } else if c == "\"" {
      var j = i + 1
      var stop_at = -1
      while j < n and stop_at < 0 {
        let d = cs.get_or(j, "")
        if d == "\\" {
          j = j + 2
        } else if d == "\"" {
          stop_at = j + 1
        } else {
          j = j + 1
        }
      }
      if stop_at < 0 {
        return Err("unterminated string")
      }
      out = out.push(cs.slice(i, stop_at).join(""))
      i = stop_at
    } else if i + 1 < n and is_two_op(c + cs.get_or(i + 1, "")) {
      out = out.push(c + cs.get_or(i + 1, ""))
      i = i + 2
    } else if is_single_op(c) {
      out = out.push(c)
      i = i + 1
    } else {
      return Err("unexpected " + c)
    }
  }
  return Ok(out)
}
